// Core tests: the 25 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every extra expected value below was computed by hand from the
// SPEC's rules; the hand derivations are listed in AUTHOR-CHECK.md
// section 2 and in the comments here.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatCm,
  formatDpi,
  formatInches,
  formatMegapixels,
  run,
} from "../public/js/core/photo-print-size.mjs";
import fixturesDoc from "./fixtures.json" with { type: "json" };

const fixtures = fixturesDoc.cases;
const coreCases = fixtures.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const baseMax = { mode: "max", pixelsW: "6000", pixelsH: "4000", dpi: "300", sizeId: "4x6" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: 24 MP at 300 DPI is 20.00 x 13.33 in and A3 is the best fit", () => {
  const outcome = run(baseMax);
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.maxWidthIn, 20);
  assert.equal(outcome.result.maxHeightIn, 13.33);
  assert.equal(outcome.result.maxWidthCm, 50.8);
  assert.equal(outcome.result.maxHeightCm, 33.9);
  assert.equal(outcome.result.bestFitSizeId, "A3");
  assert.equal(outcome.result.sizes.length, 9);
  assert.equal(outcome.result.sizes[8].sizeId, "A3");
  assert.equal(outcome.result.sizes[8].effectiveDpi, 342.1);
});

test("boundary: legal lower endpoints (1 px, DPI 1) succeed; just over fails", () => {
  // 1 px at DPI 1: 1.00 in each way, 2.5 cm each way; nothing fits.
  const tiny = run({ mode: "max", pixelsW: "1", pixelsH: "1", dpi: "1", sizeId: "4x6" });
  assert.equal(tiny.ok, true);
  assert.equal(tiny.result.maxWidthIn, 1);
  assert.equal(tiny.result.maxWidthCm, 2.5);
  assert.equal(tiny.result.bestFitSizeId, null);
  assert.deepEqual(tiny.result.sizes[0], {
    sizeId: "3x5",
    dpiLong: 0.2,
    dpiShort: 0.3,
    effectiveDpi: 0.2,
    fits: false,
    quality: "poor",
  });
  const dpiOne = run({ mode: "need", pixelsW: "6000", pixelsH: "4000", dpi: "1", sizeId: "4x6" });
  assert.equal(dpiOne.ok, true);
  assert.equal(dpiOne.result.requiredLongPx, 6);
  assert.equal(dpiOne.result.requiredShortPx, 4);
  assert.equal(dpiOne.result.megapixels, 0);
  assert.deepEqual(errorOf({ ...baseMax, pixelsW: "200001" }), {
    code: "RANGE",
    field: "pixelsW",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "0.99" }), {
    code: "RANGE",
    field: "dpi",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "1200.01" }), {
    code: "RANGE",
    field: "dpi",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "0" }), {
    code: "RANGE",
    field: "dpi",
    row: null,
  });
});

test("capacity: a 9-unit value is INPUT_LIMIT on every field, including inactive ones", () => {
  assert.deepEqual(errorOf({ ...baseMax, mode: "maxxxxxxx" }), {
    code: "INPUT_LIMIT",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, pixelsH: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "pixelsH",
    row: null,
  });
  // Inactive sizeId field: still capacity-checked in max mode.
  assert.deepEqual(errorOf({ ...baseMax, sizeId: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "sizeId",
    row: null,
  });
  // Inactive dpi field: still capacity-checked in check mode.
  assert.deepEqual(errorOf({ ...baseMax, mode: "check", dpi: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "dpi",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "dpi",
    row: null,
  });
});

test("an inactive field is capacity-checked but otherwise ignored", () => {
  // A lone surrogate in the inactive pixelsW field is ignored in need mode.
  const ignoredSurrogate = run({
    mode: "need",
    pixelsW: "\uD800",
    pixelsH: "4000",
    dpi: "300",
    sizeId: "4x6",
  });
  assert.equal(ignoredSurrogate.ok, true);
  assert.equal(ignoredSurrogate.result.requiredLongPx, 1800);
  // Arbitrary text in the inactive dpi field is ignored in check mode.
  const ignoredDpi = run({
    mode: "check",
    pixelsW: "3840",
    pixelsH: "2560",
    dpi: "garbage!",
    sizeId: "A4",
  });
  assert.equal(ignoredDpi.ok, true);
  assert.equal(ignoredDpi.result.effectiveDpi, 309.6);
  // Arbitrary text in the inactive sizeId field is ignored in max mode.
  const ignoredSize = run({ ...baseMax, sizeId: "nope" });
  assert.equal(ignoredSize.ok, true);
  assert.equal(ignoredSize.result.bestFitSizeId, "A3");
});

test("an active field reports UNICODE before EMPTY and grammar, in each field", () => {
  assert.deepEqual(errorOf({ ...baseMax, mode: "\uD800" }), {
    code: "UNICODE",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, pixelsH: "\uD800" }), {
    code: "UNICODE",
    field: "pixelsH",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "\uD800" }), {
    code: "UNICODE",
    field: "dpi",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, mode: "check", sizeId: "\uD800" }), {
    code: "UNICODE",
    field: "sizeId",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, mode: "" }), {
    code: "EMPTY",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, pixelsW: "" }), {
    code: "EMPTY",
    field: "pixelsW",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "" }), {
    code: "EMPTY",
    field: "dpi",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, mode: "need", sizeId: "" }), {
    code: "EMPTY",
    field: "sizeId",
    row: null,
  });
});

test("pixel grammar: leading zeros, signs, spaces, decimals and exponents are INTEGER_FORMAT", () => {
  for (const bad of ["01", "007", "+6000", "-6000", "6000 ", " 6000", "6000.0", "6e3", "6,000"]) {
    assert.deepEqual(errorOf({ ...baseMax, pixelsW: bad }), {
      code: "INTEGER_FORMAT",
      field: "pixelsW",
      row: null,
    });
  }
  const zeroOk = run({ ...baseMax, pixelsW: "0" });
  assert.deepEqual(zeroOk, { ok: false, error: { code: "RANGE", field: "pixelsW", row: null } });
});

test("DPI grammar: trailing dot, leading dot, three decimals and leading zeros are DECIMAL_FORMAT", () => {
  for (const bad of ["300.", ".5", "300.123", "0300", "30a", "300,5", "+300", "-300", "3e2"]) {
    assert.deepEqual(errorOf({ ...baseMax, dpi: bad }), {
      code: "DECIMAL_FORMAT",
      field: "dpi",
      row: null,
    });
  }
  // "240.50" is valid grammar and echoes as 240.5.
  const trailingZero = run({ ...baseMax, mode: "need", dpi: "240.50", sizeId: "4x6" });
  assert.equal(trailingZero.ok, true);
  assert.equal(trailingZero.result.dpi, 240.5);
  assert.equal(trailingZero.result.requiredLongPx, 1443);
  assert.equal(trailingZero.result.requiredShortPx, 962);
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...baseMax, mode: "print", pixelsW: "bad" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, pixelsW: "bad", dpi: "bad" }), {
    code: "INTEGER_FORMAT",
    field: "pixelsW",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, pixelsH: "bad", dpi: "bad" }), {
    code: "INTEGER_FORMAT",
    field: "pixelsH",
    row: null,
  });
  assert.deepEqual(errorOf({ ...baseMax, dpi: "bad", sizeId: "A6" }), {
    code: "DECIMAL_FORMAT",
    field: "dpi",
    row: null,
  });
  // Mode is checked before the other fields even when it is only an
  // ENUM failure and a later field is over capacity.
  assert.deepEqual(errorOf({ ...baseMax, mode: "print", pixelsW: "123456789" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
});

test("half-up tie: an exact .x5 rounds up (A5 short side 6.35 -> 6.4)", () => {
  // 37 px on the A5 short side: 37 x 127 / 740 = 4699/740 = 6.35
  // exactly, so R(., 1) must be 6.4, not 6.3.
  const outcome = run({ mode: "check", pixelsW: "100", pixelsH: "37", dpi: "300", sizeId: "A5" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.dpiShort, 6.4);
  assert.equal(outcome.result.dpiLong, 12.1);
  assert.equal(outcome.result.effectiveDpi, 6.4);
  assert.equal(outcome.result.quality, "poor");
});

test("quality band edge: effective DPI 149.9 is poor, one tenth below acceptable", () => {
  // 1049 px on the 5x7 long side: 1049/7 = 149.857... -> 149.9.
  const outcome = run({ mode: "check", pixelsW: "1049", pixelsH: "1000", dpi: "300", sizeId: "5x7" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.dpiLong, 149.9);
  assert.equal(outcome.result.dpiShort, 200);
  assert.equal(outcome.result.effectiveDpi, 149.9);
  assert.equal(outcome.result.quality, "poor");
});

test("cross-mode invariant: need pixels always fit, one pixel less on the long side never fits", () => {
  for (const sizeId of ["3x5", "4x6", "5x7", "6x8", "8x10", "10x12", "A5", "A4", "A3"]) {
    for (const dpi of ["150", "240", "300"]) {
      const need = run({ mode: "need", pixelsW: "6000", pixelsH: "4000", dpi, sizeId });
      assert.equal(need.ok, true);
      const { requiredLongPx, requiredShortPx } = need.result;
      const fits = run({
        mode: "max",
        pixelsW: String(requiredLongPx),
        pixelsH: String(requiredShortPx),
        dpi,
        sizeId,
      });
      assert.equal(fits.ok, true);
      const row = fits.result.sizes.find((entry) => entry.sizeId === sizeId);
      assert.equal(row.fits, true);
      // One long-side pixel less: requiredLongPx - 1 is always below
      // longIn x dpi, so this size must stop fitting.
      const oneLess = run({
        mode: "max",
        pixelsW: String(requiredLongPx - 1),
        pixelsH: String(requiredShortPx),
        dpi,
        sizeId,
      });
      assert.equal(oneLess.ok, true);
      const rowLess = oneLess.result.sizes.find((entry) => entry.sizeId === sizeId);
      assert.equal(rowLess.fits, false);
    }
  }
});

test("max and check agree on the same pixels and size", () => {
  const max = run({ ...baseMax, pixelsW: "3840", pixelsH: "2560", dpi: "300" });
  const check = run({ mode: "check", pixelsW: "3840", pixelsH: "2560", dpi: "300", sizeId: "A4" });
  assert.equal(max.ok, true);
  assert.equal(check.ok, true);
  const row = max.result.sizes.find((entry) => entry.sizeId === "A4");
  assert.equal(row.dpiLong, check.result.dpiLong);
  assert.equal(row.dpiShort, check.result.dpiShort);
  assert.equal(row.effectiveDpi, check.result.effectiveDpi);
  assert.equal(row.quality, check.result.quality);
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...baseMax, extra: "1" }), schema);
  const missing = { ...baseMax };
  delete missing.dpi;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...baseMax, pixelsW: 6000 }), schema);
  assert.deepEqual(errorOf({ ...baseMax, dpi: null }), schema);
  assert.deepEqual(errorOf(["max"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("max"), schema);
  const withGetter = { ...baseMax };
  Object.defineProperty(withGetter, "pixelsW", {
    enumerable: true,
    get() {
      return "6000";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...baseMax, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...baseMax };
  stringObject.pixelsW = new String("6000");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...baseMax };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...baseMax, dpi: "1201" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("display formatting: inches 2 decimals, cm 1 decimal, DPI 1 decimal, megapixels 2 decimals", () => {
  assert.equal(formatInches(20), "20.00");
  assert.equal(formatInches(13.33), "13.33");
  assert.equal(formatInches(1), "1.00");
  assert.equal(formatCm(50.8), "50.8");
  assert.equal(formatCm(21), "21.0");
  assert.equal(formatDpi(300), "300.0");
  assert.equal(formatDpi(149.9), "149.9");
  assert.equal(formatMegapixels(8.7), "8.70");
  assert.equal(formatMegapixels(0), "0.00");
});
